#!/bin/sh
# Install the capturefab command @VERSION_LABEL@ for the current user.
#
# Generated by scripts/site-release.py from web/releases.json; do not edit
# web/install.sh by hand. The release files and their SHA-256 checksums are
# written into this script, so it downloads from the official release, checks
# the checksum before extracting anything, and never runs sudo.
#
#   curl -fsSL https://capturefab.com/install.sh | sh
#   curl -fsSLO https://capturefab.com/install.sh && less install.sh && sh install.sh --dry-run
#
# Options (after `sh -s --` when piping):
#   --prefix DIR    where releases go (default ${XDG_DATA_HOME:-~/.local/share}/capturefab)
#   --bin-dir DIR   where the capturefab command goes (default ~/.local/bin)
#   --dry-run       print the selected file, URL and checksum, then exit
#   --upgrade       install this release over an earlier install
#   --uninstall     remove installed releases and their command link; keep user data
set -eu

VERSION='@VERSION@'
SITE='@SITE@'

# Sets name, url and expected for an operating system and processor.
asset() {
  case "$1/$2" in
@ASSETS@    *) return 1 ;;
  esac
}

say() { printf '%s\n' "$*"; }
fail() { printf 'capturefab install: %s\n' "$*" >&2; exit 1; }

prefix=''
bin_dir="${HOME:?HOME is not set}/.local/bin"
dry_run=0
action=install
while [ $# -gt 0 ]; do
  case "$1" in
    --prefix) [ $# -ge 2 ] || fail "--prefix needs a directory"; prefix=$2; shift 2 ;;
    --prefix=*) prefix=${1#*=}; shift ;;
    --bin-dir) [ $# -ge 2 ] || fail "--bin-dir needs a directory"; bin_dir=$2; shift 2 ;;
    --bin-dir=*) bin_dir=${1#*=}; shift ;;
    --dry-run) dry_run=1; shift ;;
    --upgrade|--uninstall)
      [ "$action" = install ] || fail "choose only one of --upgrade and --uninstall"
      action=${1#--}; shift ;;
    -h|--help) say "Usage: sh install.sh [--upgrade | --uninstall] [--prefix DIR] [--bin-dir DIR] [--dry-run]"; exit 0 ;;
    *) fail "unknown option: $1 (use --help)" ;;
  esac
done
# The command symlink must name an absolute target: a relative one would
# resolve against the bin directory, not the directory the user ran this in.
case "$prefix" in ''|/*) ;; *) prefix="$PWD/$prefix" ;; esac
case "$bin_dir" in '' ) fail "--bin-dir needs a nonempty directory" ;; /*) ;; *) bin_dir="$PWD/$bin_dir" ;; esac
base=${prefix:-${XDG_DATA_HOME:-$HOME/.local/share}/capturefab}
case "$base" in /*) ;; *) base="$PWD/$base" ;; esac
[ "$base" != / ] || fail "the install prefix cannot be the filesystem root"
[ ! -L "$base" ] || fail "the install prefix must not be a symbolic link: $base"

# Recognize our versioned releases, including installs made before markers
# were added. Never remove arbitrary children of a custom prefix or follow
# symlinks out of it. README.txt is part of every official CLI package.
managed_release() {
  release_leaf=${1##*/}
  printf '%s\n' "$release_leaf" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+(\.previous(-[0-9]+)?)?$' || return 1
  release_version=${release_leaf%%.previous*}
  [ -d "$1" ] && [ ! -L "$1" ] || return 1
  if [ -f "$1/.capturefab-install" ] && [ "$(cat "$1/.capturefab-install")" = capturefab-installer-v1 ]; then return 0; fi
  [ -f "$1/capturefab" ] && [ -f "$1/README.txt" ] || return 1
  readme=$(head -n 1 "$1/README.txt")
  case "$readme" in "Capturefab $release_version"|"Capturefab $release_version ("*) return 0 ;; *) return 1 ;; esac
}

if [ "$action" = uninstall ]; then
  removed=0
  previous=''
  if [ -L "$bin_dir/capturefab" ]; then previous=$(readlink "$bin_dir/capturefab"); fi
  previous_dir=''
  if [ -n "$previous" ] && [ "${previous##*/}" = capturefab ]; then
    case "$previous" in /*) ;; *) previous="$bin_dir/$previous" ;; esac
    previous_dir=$(cd -P "${previous%/*}" 2>/dev/null && pwd -P) || previous_dir=''
  fi
  for old in "$base"/*; do
    managed_release "$old" || continue
    old_dir=$(cd -P "$old" && pwd -P)
    if [ "$previous_dir" = "$old_dir" ]; then
      say "Remove command: $bin_dir/capturefab"
      if [ "$dry_run" = 0 ]; then rm -f "$bin_dir/capturefab"; fi
    fi
    say "Remove release: $old"
    if [ "$dry_run" = 0 ]; then rm -rf "$old"; fi
    removed=1
  done
  if [ "$dry_run" = 0 ] && [ "$removed" = 1 ]; then rmdir "$base" 2>/dev/null || true; fi
  if [ "$removed" = 0 ]; then say "No installer-managed Capturefab releases found in $base."; fi
  say "Presets, saved sign-ins, caches and files outside the release folders are unchanged."
  exit 0
fi

# Empty until a command-line release is published: releases up to 0.5.0 were
# the desktop app, which this script does not install.
[ -n "$VERSION" ] || fail "no command-line release is published yet (0.5.0 and earlier are the desktop app); see ${SITE}downloads.html or build from source"

kernel=$(uname -s)
case "$kernel" in
  Darwin) os=macos ;;
  Linux) os=linux ;;
  MINGW*|MSYS*|CYGWIN*) fail "on Windows, run this in PowerShell instead: irm ${SITE}install.ps1 | iex" ;;
  *) fail "no Capturefab build for $kernel; see ${SITE}downloads.html" ;;
esac

machine=$(uname -m)
if [ "$os" = linux ] && command -v dpkg >/dev/null 2>&1; then
  # The installed userspace decides, not the processor: 32-bit Raspberry Pi OS
  # reports aarch64 from uname -m.
  machine=$(dpkg --print-architecture)
fi
if [ "$os" = macos ] && [ "$(sysctl -n sysctl.proc_translated 2>/dev/null || echo 0)" = 1 ]; then
  machine=arm64 # A Rosetta shell on Apple silicon.
fi
case "$machine" in
  x86_64|amd64) arch=x86_64 ;;
  aarch64|arm64) arch=aarch64 ;;
  armhf|armel|armv6l|armv7l|i386|i686) fail "there is no build for 32-bit $machine systems; install a 64-bit operating system (Raspberry Pi 3 and later run 64-bit Raspberry Pi OS)" ;;
  *) fail "no Capturefab build for $machine; see ${SITE}downloads.html" ;;
esac

name='' url='' expected=''
asset "$os" "$arch" || fail "Capturefab $VERSION has no published $os $arch build; see ${SITE}downloads.html"
if [ -n "${CAPTUREFAB_INSTALL_BASE_URL:-}" ]; then
  # A mirror or test server; the checksum above still decides.
  url="${CAPTUREFAB_INSTALL_BASE_URL%/}/$name"
fi

case "$name" in
  *.tar.gz) ;;
  # Releases up to 0.5.0 shipped the macOS desktop app as a disk image.
  *) fail "Capturefab $VERSION for $os is $name, which this script cannot install; download it from ${SITE}downloads.html" ;;
esac

if [ "$dry_run" = 1 ]; then
  say "Capturefab $VERSION for $os $arch"
  say "file:   $name"
  say "url:    $url"
  say "sha256: $expected"
  exit 0
fi

work=$(mktemp -d "${TMPDIR:-/tmp}/capturefab-install.XXXXXX")
stage='' backup='' link_work=''
cleanup() {
  rm -rf "$work"
  if [ -n "$stage" ]; then rm -rf "$stage"; fi
  if [ -n "$link_work" ]; then rm -rf "$link_work"; fi
  if [ -n "$backup" ] && [ ! -e "$dest" ]; then mv "$backup" "$dest"; fi
}
trap cleanup EXIT
trap 'exit 130' INT TERM

say "Downloading $name"
if command -v curl >/dev/null 2>&1; then
  curl -fL --retry 2 --progress-bar -o "$work/$name" "$url" || fail "download failed: $url"
elif command -v wget >/dev/null 2>&1; then
  wget -q -O "$work/$name" "$url" || fail "download failed: $url"
else
  fail "curl or wget is needed to download $url"
fi

if command -v sha256sum >/dev/null 2>&1; then
  actual=$(sha256sum "$work/$name")
elif command -v shasum >/dev/null 2>&1; then
  actual=$(shasum -a 256 "$work/$name")
elif command -v openssl >/dev/null 2>&1; then
  actual=$(openssl dgst -sha256 -r "$work/$name")
else
  fail "sha256sum, shasum or openssl is needed to check the download"
fi
actual=$(printf '%s' "${actual%% *}" | tr 'A-F' 'a-f')
[ "$actual" = "$expected" ] || fail "checksum mismatch for $name: expected $expected, got $actual. Nothing was installed."
say "Checksum OK: $expected"

stem=${name%.tar.gz}
mkdir "$work/x"
tar -xzf "$work/$name" -C "$work/x" || fail "cannot extract $name"
if [ ! -f "$work/x/$stem/capturefab" ] || [ ! -x "$work/x/$stem/capturefab" ]; then
    fail "$name has no capturefab executable"
fi
dest="$base/$VERSION"
"$work/x/$stem/capturefab" --version || fail "the downloaded capturefab did not start; the current install is unchanged"
mkdir -p "$base" "$bin_dir"
if [ -e "$dest" ] || [ -L "$dest" ]; then
  managed_release "$dest" || fail "refusing to replace an unrecognized release folder: $dest"
fi
if [ -e "$bin_dir/capturefab" ] || [ -L "$bin_dir/capturefab" ]; then
  [ -L "$bin_dir/capturefab" ] && [ ! -d "$bin_dir/capturefab" ] || fail "refusing to replace a file or directory at $bin_dir/capturefab; move it aside first"
fi
# Stage on the destination volume, so publishing the directory is a rename.
stage=$(mktemp -d "$base/.install.XXXXXX")
mv "$work/x/$stem" "$stage/release"
printf '%s\n' capturefab-installer-v1 > "$stage/release/.capturefab-install"
link_work=$(mktemp -d "$bin_dir/.capturefab-link.XXXXXX")
target="$dest/capturefab"
ln -s "$target" "$link_work/capturefab"
if [ -e "$dest" ]; then
  backup="$dest.previous-$$"
  [ ! -e "$backup" ] && [ ! -L "$backup" ] || fail "backup already exists: $backup"
  mv "$dest" "$backup"
fi
mv "$stage/release" "$dest"

# What an earlier desktop release (0.5 and before) installed: the command
# link pointed into Capturefab.app on macOS, and Linux had a launcher entry.
previous=''
if [ -L "$bin_dir/capturefab" ]; then previous=$(readlink "$bin_dir/capturefab" || true); fi
if ! mv -f "$link_work/capturefab" "$bin_dir/capturefab"; then
  rm -rf "$dest"
  fail "could not publish the command link; the earlier release will be restored"
fi
if [ -n "$backup" ]; then rm -rf "$backup"; backup=''; fi

say "Installed Capturefab $VERSION in $dest"
say "Command: $bin_dir/capturefab -> $target"
"$bin_dir/capturefab" --version || fail "the installed capturefab did not start"

case "$previous" in
  *Capturefab.app/*)
    say ""
    say "The capturefab command no longer runs the desktop app at ${previous%%/Contents/*}."
    say "This release is the command-line tool only. The app itself is unchanged: keep it to"
    say "use the 0.5 desktop app, or delete it (drag it to the Trash) when you no longer need it."
    ;;
esac
for app in "$HOME/Applications/Capturefab.app" "/Applications/Capturefab.app"; do
  if [ -d "$app" ] && [ "${previous%%/Contents/*}" != "$app" ]; then
    say ""
    say "A Capturefab desktop app (0.5 or earlier) is still in ${app%/*}; delete it when you no longer need it."
  fi
done
share=${XDG_DATA_HOME:-$HOME/.local/share}
if [ -f "$share/applications/capturefab.desktop" ] && grep -q '^Exec=.*capturefab' "$share/applications/capturefab.desktop"; then
  # The launcher entry and icons an earlier install added; with no desktop
  # app they would open nothing.
  rm -f "$share/applications/capturefab.desktop"
  for icon in "$share"/icons/hicolor/*/apps/capturefab.png "$share"/icons/hicolor/*/apps/capturefab.svg; do
    if [ -f "$icon" ]; then rm -f "$icon"; fi
  done
  say ""
  say "Removed the desktop launcher entry an earlier Capturefab install added."
fi
for old in "$base"/*; do
  if [ -d "$old" ] && [ "$old" != "$dest" ] && [ -e "$old/capturefab" ]; then
    say ""
    say "Earlier Capturefab releases stay in $base; delete the ones you no longer need."
    break
  fi
done

found=$(command -v capturefab 2>/dev/null || true)
if [ -n "$found" ] && [ "$found" != "$bin_dir/capturefab" ]; then
  say ""
  say "Your PATH finds another capturefab first: $found"
  say "Remove its folder from PATH (an earlier install may have added /Applications/Capturefab.app/Contents/MacOS"
  say "to ~/.zprofile), or put $bin_dir first."
fi
case ":${PATH:-}:" in
  *":$bin_dir:"*) ;;
  *)
    say ""
    say "$bin_dir is not on your PATH. Add it, then open a new terminal:"
    case "${SHELL:-}" in
      */fish) say "  fish_add_path $bin_dir" ;;
      */zsh) say "  echo 'export PATH=\"$bin_dir:\$PATH\"' >> ~/.zshrc" ;;
      *) say "  echo 'export PATH=\"$bin_dir:\$PATH\"' >> ~/.profile" ;;
    esac
    ;;
esac
say ""
say "Next: capturefab doctor"
say "Try:  capturefab capture -c sim:0 -o 'first-{seq}.png'"
say "For AI agents: capturefab schema"
if [ "$os" = linux ]; then
  say "USB3 Vision and GigE Vision cameras can need system settings; capturefab doctor prints each fix."
  say "USB3 Vision udev rule: $dest/INSTALL-USB.txt"
fi
if [ "$os" = macos ]; then
  say "The first camera or network command asks for Camera and Local Network access for your terminal app."
fi
